// Stands in for zustand's devtools middleware: a file under a zustand/ folder that calls connect().
export function connectLikeZustand(name: string) {
  const connection = (globalThis as any).__REDUX_DEVTOOLS_EXTENSION__.connect({ name })
  // Used before returning, as zustand does: a bare `return connect()` is a tail call, whose frame JavaScriptCore drops.
  connection.subscribe(() => {})
  return connection
}
